#!/usr/bin/env python3
from datetime import datetime, timedelta

# ---------- Helper functions ----------
def to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_str(m: int) -> str:
    h = m // 60
    mins = m % 60
    return f"{h:02d}:{mins:02d}"

def subtract_intervals(base, busy):
    """Return list of intervals in `base` after removing all `busy` intervals."""
    result = []
    for b_start, b_end in sorted(busy):
        new_base = []
        for s, e in base:
            if b_end <= s or b_start >= e:
                new_base.append((s, e))
            else:
                if b_start > s:
                    new_base.append((s, b_start))
                if b_end < e:
                    new_base.append((b_end, e))
        base = new_base
    return base

def intersect_intervals(a, b):
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            res.append((s, e))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return res

# ---------- Data ----------
WORK_START = to_min("09:00")
WORK_END   = to_min("17:00")
MEETING_DURATION = 60  # minutes

weekdays = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]

# Busy intervals (start, end) as strings per participant per day
diane_busy = {
    "Monday":    [("12:00", "12:30"), ("15:00", "15:30")],
    "Tuesday":   [("10:00", "11:00"), ("11:30", "12:00"), ("12:30", "13:00"), ("16:00", "17:00")],
    "Wednesday": [("09:00", "09:30"), ("14:30", "15:00"), ("16:30", "17:00")],
    "Thursday":  [("15:30", "16:30")],
    "Friday":    [("09:30", "11:30"), ("14:30", "15:00"), ("16:00", "17:00")]
}

matthew_busy = {
    "Monday":    [("09:00", "10:00"), ("10:30", "17:00")],
    "Tuesday":   [("09:00", "17:00")],
    "Wednesday": [("09:00", "11:00"), ("12:00", "14:30"), ("16:00", "17:00")],
    "Thursday":  [("09:00", "16:00")],
    "Friday":    [("09:00", "17:00")]
}

# Convert busy intervals to minutes
def convert(schedule):
    out = {}
    for day, intervals in schedule.items():
        out[day] = [(to_min(s), to_min(e)) for s, e in intervals]
    return out

diane_busy_min = convert(diane_busy)
matthew_busy_min = convert(matthew_busy)

# ---------- Search ----------
answer = None
for day in weekdays:
    # Build free intervals for each participant
    work_interval = [(WORK_START, WORK_END)]
    d_free = subtract_intervals(work_interval, diane_busy_min.get(day, []))
    m_free = subtract_intervals(work_interval, matthew_busy_min.get(day, []))

    # Intersection of free times
    common = intersect_intervals(d_free, m_free)

    for start, end in common:
        # earliest possible start within this interval
        if end - start >= MEETING_DURATION:
            candidate_start = start
            # Preference: avoid Wednesday before 12:30 (750)
