                # shift to 12:30 if still fits inside the interval
                candidate_start = to_min("12:30")
                if candidate_start + MEETING_DURATION > end:
                    continue  # cannot fit after preference shift
            # Confirm still within interval
            if candidate_start + MEETING_DURATION <= end:
                answer = [day, to_str(candidate_start), to_str(candidate_start + MEETING_DURATION)]
                break
    if answer:
        break

