    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_text(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"

def is_available(person, day, start, end):
    for busy_start, busy_end in SCHEDULES[person].get(day, []):
        bs = to_minutes(busy_start)
        be = to_minutes(busy_end)
        if start < be and end > bs:
            return False
    return True

def earliest_slot():
    for day in DAYS:
        for start in range(WORK_START, WORK_END, 30):
            end = start + MEETING_DURATION
            if end > WORK_END:
                continue
            if all(is_available(person, day, start, end) for person in SCHEDULES):
                return [day, to_text(start), to_text(end)]

