import itertools

def time_to_min(text):
    text = text.strip().upper()
    if text.endswith("AM"):
        period = "AM"
        body = text[:-2]
    else:
        period = "PM"
        body = text[:-2]
    hour, minute = map(int, body.split(":"))
    if period == "AM":
        if hour == 12:
            hour = 0
    else:
        if hour != 12:
            hour += 12
    return hour * 60 + minute

def fmt_min(minutes):
    hour, minute = divmod(minutes, 60)
    period = "AM" if hour < 12 else "PM"
    hour %= 12
    if hour == 0:
        hour = 12
    return f"{hour}:{minute:02d}{period}"

START_TIME = time_to_min("9:00AM")
START_LOCATION = "The Castro"

TRAVEL = {
    ("The Castro", "Alamo Square"): 8,
    ("The Castro", "Union Square"): 19,
    ("The Castro", "Chinatown"): 20,
    ("Alamo Square", "The Castro"): 8,
    ("Alamo Square", "Union Square"): 14,
    ("Alamo Square", "Chinatown"): 16,
    ("Union Square", "The Castro"): 19,
    ("Union Square", "Alamo Square"): 15,
    ("Union Square", "Chinatown"): 7,
    ("Chinatown", "The Castro"): 22,
    ("Chinatown", "Alamo Square"): 17,
    ("Chinatown", "Union Square"): 7,
}

FRIENDS = [
    ("Emily", "Alamo Square", time_to_min("11:45AM"), time_to_min("3:15PM"), 105),
    ("Barbara", "Union Square", time_to_min("4:45PM"), time_to_min("6:15PM"), 60),
    ("William", "Chinatown", time_to_min("5:15PM"), time_to_min("7:00PM"), 105),
]

def build_schedule(order):
    events = [f"You start at {START_LOCATION} at {fmt_min(START_TIME)}."]
    loc = START_LOCATION
    now = START_TIME

    for name, friend_loc, window_start, window_end, duration in order:
        if loc != friend_loc:
            travel = TRAVEL[(loc, friend_loc)]
            arrival = now + travel
            if arrival > window_end:
                return None
            events.append(
                f"You travel to {friend_loc} in {travel} minutes and arrive at {fmt_min(arrival)}."
            )
            now = arrival
            loc = friend_loc

        meet_start = max(now, window_start)
        meet_end = meet_start + duration
        if meet_end > window_end:
            return None

        if meet_start > now:
            events.append(f"You wait until {fmt_min(meet_start)}.")

        events.append(
            f"You meet {name} for {duration} minutes from {fmt_min(meet_start)} to {fmt_min(meet_end)}."
        )
        now = meet_end

    return events, now

def solve():
    for count in range(len(FRIENDS), -1, -1):
        best = None
        best_end = None

        for order in itertools.permutations(FRIENDS, count):
            result = build_schedule(order)
            if result is None:
                continue

            events, end_time = result
            if best is None or end_time < best_end:
                best = events
                best_end = end_time

        if best is not None:
            print(best)
            return

